package com.trombokendu.chronos.persistence;import java.sql.*;import com.trombokendu.chronos.domain.*;public final class UnitOfWork implements AutoCloseable{private final Connection c;private boolean done;public UnitOfWork(Connection c){this.c=c;try{c.setAutoCommit(false);}catch(SQLException e){throw new PersistenceException("begin failed",e);}}public Savepoint savepoint(){try{return c.setSavepoint();}catch(SQLException e){throw new PersistenceException("savepoint failed",e);}}public void commit(){try{c.commit();done=true;}catch(SQLException e){throw new PersistenceException("commit failed",e);}}public void rollback(){try{c.rollback();done=true;}catch(SQLException e){throw new PersistenceException("rollback failed",e);}}public void close(){if(!done)rollback();try{c.setAutoCommit(true);}catch(SQLException e){throw new PersistenceException("reset failed",e);}}}
